-- 4. 产地实拍与溯源档案
INSERT INTO tb_origin_archive (id, product_id, soil_quality, water_environment, field_photos, pesticide_test_report, test_result, origin_story) VALUES
(1, 1, '海拔2600米高山红壤，富含微量元素硒和钾，透气排水良好', '源自青藏高原东南边缘雪山纯净融水，无重金属工业污染', '["https://images.unsplash.com/photo-1560806887-1e4cd0b6cbd6?w=600"]', 'https://images.unsplash.com/photo-1584727638096-042c45049ebe?w=800', '经过SGS与农业农村部质检中心320项农残专项筛查，农残0检出', '盐源县拥有得天独厚的紫外线照射与近15度的昼夜温差，使苹果自然凝结半透明蜜心。好产品，不烧心！'),
(2, 13, '寿光特级草炭土改良土质，施用充分发酵黄豆有机发酵肥料', '全封闭地下50米深井水源，经多介质石英砂与反渗透软化过滤', '["https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=600"]', 'https://images.unsplash.com/photo-1584727638096-042c45049ebe?w=800', '达到无公害蔬菜绿色认证，抽检各项指标全部优于国标', '每一棵番茄苗均采用熊蜂天然授粉，找回小时候自然熟浓郁番茄风味。好产品，不烧心！');

